<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;require ROOT.'/includes/panel.php';$sales=one('SELECT SUM(amount) n FROM orders WHERE status IN (\'paid\',\'delivered\')');$tickets=one('SELECT COUNT(*) n FROM tickets WHERE status<>\'closed\'');$licenses=one('SELECT COUNT(*) n FROM licenses WHERE status=\'active\' AND (expires_at IS NULL OR expires_at>=?)',[date('Y-m-d')]);?><h1>Seu negócio, em perspectiva.</h1><div class="stats"><div class="card"><small>Vendas confirmadas • total</small><b><?=e(money($sales['n']??0))?></b></div><div class="card"><small>Chamados abertos</small><b><?=$tickets['n']?></b></div><div class="card"><small>Licenças ativas</small><b><?=$licenses['n']?></b></div></div><p class="notice" style="margin-top:24px">Os valores refletem pedidos marcados manualmente como pagos ou entregues. A plataforma não recebe pagamentos automaticamente.</p><h2>Últimos pedidos</h2><div class="table-wrap"><table><tr><th>Pedido</th><th>Cliente</th><th>Produto</th><th>Status</th></tr><?php foreach(rows('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 10') as $o):?><tr><td><a href="<?=e(url('admin/pedidos.php?id='.$o['id']))?>">#<?=$o['id']?></a></td><td><?=e($o['name'])?></td><td><?=e($o['product_name'])?></td><td><?=e($o['status'])?></td></tr><?php endforeach;?></table></div><?php require ROOT.'/includes/endpanel.php';?>
